KG42.register("rules-b18b45d02dfd169aa01df9c4",{"id":"14-stackelberg_pv_sharing::v141-c-R008","paper":"14-stackelberg_pv_sharing","record":{"rule_id":"v141-c-R008","mechanism_id":"v141-a-M01","name":"Local clearing price","process_stage":"pricing","market_meaning":"The MGO determines the internal buying and selling prices simultaneously and obtains next-slot prices by solving the pricing optimization. Scope: Stackelberg ESM internal buying and selling prices for the next time slot. The MGO increases the internal selling price p_s in the reported shortage cases. Scope: Reported Stackelberg case study, time slots 10, 11, 12, and 16. Condition: Selling energy is less than buying energy in these reported time slots. The MGO decreases the internal buying price p_b in the reported surplus cases. Scope: Reported Stackelberg case study, time slots 13 and 14. Condition: Selling energy is more than buying energy in these reported time slots. Internal buying and selling prices are decision variables for maximizing the MGO's own profit, subject to λ^s ≤ p_s \u003c p_b ≤ λ^b. Scope: Stackelberg ESM internal-price optimization. Initial internal selling and buying prices may be set to λ^s and λ^b, respectively. Scope: Initialization of internal prices for each time slot. Condition: Initial price setting. Select the internal price pair by comparing MGO profit at the optima of D_1 and D_2, where D_1 applies when E^b \u003c E^s and D_2 applies when E^b ≥ E^s. Scope: Selection of optimal internal prices across the surplus and nonsurplus pricing regions. The internal selling and buying prices remain at λ^s and λ^b, respectively, in these reported time slots. Scope: Reported Stackelberg case study, time slots 7 and 17–19 only. Condition: PV energy is entirely self-consumed and no energy is feasible to trade inside the microgrid.","independence_rationale":"Relations governed by the approved function pricing.local under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["coordination.local_operator","pricing.local"],"E":[{"edge_id":"v141-c-R008-E001","source":"coordination.local_operator","target":"pricing.local","type":"links","constraint_ids":["v141-c-R008-C001","v141-c-R008-C002","v141-c-R008-C003"],"evidence_ids":["v141-b-g01-e006","v141-b-g01-e019","v141-b-g02-E12"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"Initialization of internal prices for each time slot. | Reported Stackelberg case study, time slots 10, 11, 12, and 16. | Reported Stackelberg case study, time slots 13 and 14. | Reported Stackelberg case study, time slots 7 and 17–19 only. | Selection of optimal internal prices across the surplus and nonsurplus pricing regions. | Stackelberg ESM internal buying and selling prices for the next time slot. | Stackelberg ESM internal-price optimization.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e006","v141-b-g01-e007","v141-b-g01-e008","v141-b-g01-e014","v141-b-g01-e019","v141-b-g02-E11","v141-b-g02-E12","v141-b-g03-E09","v141-b-g03-E11"]},"x":[{"variable_id":"x_p_s","symbol":"p_s","meaning":"Internal selling price set by the MGO for the next time slot; a decision variable in the MGO profit-maximization and bounded by the internal-price constraint.","kind":"operational","domain":"real scalar per time slot; λ^s ≤ p_s \u003c p_b ≤ λ^b","unit":"CNY/kWh","indices":["time slot"],"evidence_ids":["v141-b-g01-e007","v141-b-g01-e014","v141-b-g01-e019"]},{"variable_id":"x_p_b","symbol":"p_b","meaning":"Internal buying price set by the MGO for the next time slot; a decision variable in the MGO profit-maximization and bounded by the internal-price constraint.","kind":"operational","domain":"real scalar per time slot; λ^s ≤ p_s \u003c p_b ≤ λ^b","unit":"CNY/kWh","indices":["time slot"],"evidence_ids":["v141-b-g01-e007","v141-b-g01-e014","v141-b-g01-e019"]}],"theta":[{"parameter_id":"theta_lambda_s","symbol":"λ^s","meaning":"Utility-grid export (feed-in) price; constant export price, lower than import price λ^b. Case-study calibration λ^s = 0.4 CNY/kWh.","value":{"kind":"numeric","number_value":0.4,"text_value":null},"unit":"CNY/kWh","indices":[],"evidence_ids":["v141-b-g01-e007","v141-b-g02-E01"]},{"parameter_id":"theta_lambda_b","symbol":"λ^b","meaning":"Utility-grid import price; constant import price, higher than export price λ^s. Case-study calibration λ^b = 1.0 CNY/kWh.","value":{"kind":"numeric","number_value":1.0,"text_value":null},"unit":"CNY/kWh","indices":[],"evidence_ids":["v141-b-g01-e007","v141-b-g02-E01"]}],"phi":[{"constraint_id":"v141-c-R008-C001","kind":"procedural","role":"core","statement":"The MGO determines the internal buying and selling prices simultaneously and obtains next-slot prices by solving the pricing optimization. Scope: Stackelberg ESM internal buying and selling prices for the next time slot.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","pricing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e006","v141-b-g01-e019"]},{"constraint_id":"v141-c-R008-C002","kind":"procedural","role":"core","statement":"The MGO increases the internal selling price p_s in the reported shortage cases. Scope: Reported Stackelberg case study, time slots 10, 11, 12, and 16. Condition: Selling energy is less than buying energy in these reported time slots.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","pricing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E12"]},{"constraint_id":"v141-c-R008-C003","kind":"procedural","role":"core","statement":"The MGO decreases the internal buying price p_b in the reported surplus cases. Scope: Reported Stackelberg case study, time slots 13 and 14. Condition: Selling energy is more than buying energy in these reported time slots.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","pricing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E12"]},{"constraint_id":"v141-c-R008-C004","kind":"mathematical","role":"core","statement":"Internal buying and selling prices are decision variables for maximizing the MGO's own profit, subject to λ^s ≤ p_s \u003c p_b ≤ λ^b. Scope: Stackelberg ESM internal-price optimization.","expression":"\\max_{p_b,p_s} R(p_b,p_s)\\quad \\text{s.t.}\\quad \\lambda^s \\le p_s \u003c p_b \\le \\lambda^b,\\quad R(p_b,p_s)=\\begin{cases} p_b E^b - p_s E^s + \\lambda^s(E^s-E^b), & E^s>E^b,\\\\ p_b E^b - p_s E^s + \\lambda^b(E^s-E^b), & E^s\\le E^b. \\end{cases}","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":["x_p_b","x_p_s"],"parameter_refs":["theta_lambda_s","theta_lambda_b"],"evidence_ids":["v141-b-g01-e007","v141-b-g01-e014"]},{"constraint_id":"v141-c-R008-C005","kind":"mathematical","role":"core","statement":"Initial internal selling and buying prices may be set to λ^s and λ^b, respectively. Scope: Initialization of internal prices for each time slot. Condition: Initial price setting.","expression":"p_s = \\lambda^s,\\quad p_b = \\lambda^b \\quad \\text{(initialization for each time slot)}","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":["x_p_s","x_p_b"],"parameter_refs":["theta_lambda_s","theta_lambda_b"],"evidence_ids":["v141-b-g01-e008"]},{"constraint_id":"v141-c-R008-C006","kind":"mathematical","role":"core","statement":"Select the internal price pair by comparing MGO profit at the optima of D_1 and D_2, where D_1 applies when E^b \u003c E^s and D_2 applies when E^b ≥ E^s. Scope: Selection of optimal internal prices across the surplus and nonsurplus pricing regions.","expression":"(p_b^*,p_s^*) = \\operatorname*{argmax}_{(p_b,p_s)}\\left(R(p_{bD_1}^*,p_{sD_1}^*), R(p_{bD_2}^*,p_{sD_2}^*)\\right),\\quad (p_b,p_s)\\in D_1 \\text{ if } E^b\u003cE^s,\\; (p_b,p_s)\\in D_2 \\text{ if } E^b\\ge E^s","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":["x_p_b","x_p_s"],"parameter_refs":[],"evidence_ids":["v141-b-g03-E09","v141-b-g03-E11"]},{"constraint_id":"v141-c-R008-C007","kind":"mathematical","role":"core","statement":"The internal selling and buying prices remain at λ^s and λ^b, respectively, in these reported time slots. Scope: Reported Stackelberg case study, time slots 7 and 17–19 only. Condition: PV energy is entirely self-consumed and no energy is feasible to trade inside the microgrid.","expression":"\\forall t\\in\\{7,17,18,19\\}:\\; p_s(t)=\\lambda^s,\\; p_b(t)=\\lambda^b \\quad \\text{when PV energy is entirely self-consumed and no internal trade is feasible}","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":["x_p_s","x_p_b"],"parameter_refs":["theta_lambda_s","theta_lambda_b"],"evidence_ids":["v141-b-g02-E11"]},{"constraint_id":"v141-c-R008-C008","kind":"mathematical","role":"supporting","statement":"The MGO profit objective for internal-price optimization is the piecewise function R(p_b,p_s) in (5): it collects p_b E^b from buyers and pays p_s E^s to sellers, and settles the net imbalance with the utility grid at λ^s when E^s > E^b or at λ^b when E^s ≤ E^b. Scope: Stackelberg ESM internal-price optimization.","expression":"R(p_b,p_s)=\\begin{cases} p_b E^b - p_s E^s + \\lambda^s(E^s-E^b), & E^s>E^b,\\\\ p_b E^b - p_s E^s + \\lambda^b(E^s-E^b), & E^s\\le E^b. \\end{cases}","formalization_origin":"source","template_id":null,"members":["pricing.local","coordination.local_operator"],"variable_refs":["x_p_b","x_p_s"],"parameter_refs":["theta_lambda_s","theta_lambda_b"],"evidence_ids":["v141-b-g01-e014","v141-b-g01-e007"]}],"pi":[{"evidence_id":"v141-b-g01-e006","location":{"location_id":"src-ed046424ff-p02-c1r4__v141-a-M01-participation","page":2,"printed_page":null,"section":"I. INTRODUCTION","anchor_text":"g p p mentioned studies, two main differences have been made. The as ﬁrst is the role of participant","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"unknown"},"source_text":"In this paper, every prosumer has equal privilege which means prosumers are participated in the microgrid operation equipotently. Thus, we select MGO as the leader, which means that the MGO determines the buying and selling prices simultaneously. And the prosumers act as followers to adjust their energy consumption behaviors according to the time-varying prices."},{"evidence_id":"v141-b-g01-e007","location":{"location_id":"src-ed046424ff-p03-c1r2__v141-a-M01-pricing","page":3,"printed_page":null,"section":"II. SYSTEM MODEL","anchor_text":"imize the own proﬁt under constraint λ ≤ps \u003c pb ≤λ . The sl prosumers can get beneﬁts from the energ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"condition"},"source_text":"In order to coordinate the sharing process among the prosumers, the internal selling (p_s) and buying prices (p_b) are set by the MGO. According to the feed-in tariff of some countries, the import and export prices between MGO and utility grid are constant. Generally, the export price λ^s is lower than the import price λ^b for encouraging local consumption of PV energy, and thus reduce the impact on the utility grid. The goal of MGO is to maximize the own profit under constraint λ^s ≤ p_s \u003c p_b ≤ λ^b. The prosumers can get benefits from the energy sharing compared to trade with the utility grid directly."},{"evidence_id":"v141-b-g01-e008","location":{"location_id":"src-ed046424ff-p03-c2r1__v141-a-M01-clearing","page":3,"printed_page":null,"section":"II.A Utility Model of PV Prosumers","anchor_text":"IEEE TRANSACTIONS ON INDUSTRIAL INFORMATICS, VOL. 13, NO. 3, JUNE 2017 λb, It can be easily proved t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"For each time slot, the initial internal prices p_s and p_b can be set as λ^s and λ^b, respectively."},{"evidence_id":"v141-b-g01-e014","location":{"location_id":"src-ed046424ff-p03-c2r3__v141-a-M01-pricing","page":3,"printed_page":null,"section":"II.B Profit Model of MGO","anchor_text":"( n n) ( ) act n∈B ave Es = (Egn −xn). (4) n∈S 0 In order to maximize PV energy sharing among prosum","equation_id":"(5)","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"In order to maximize PV energy sharing among prosumers, the profit function of the MGO is formulated as R(p_b, p_s) = { p_b E^b − p_s E^s + λ^s(E^s − E^b), E^s > E^b; p_b E^b − p_s E^s + λ^b(E^s − E^b), E^s ≤ E^b } (5) where the internal prices p_b and p_s are decision variables. MGO sells energy to buyers with price p_b and purchases energy from sellers with price p_s, which also trade with the utility grid simultaneously in order to keep the supply–demand balance in the microgrid. If E^s > E^b, MGO sells surplus PV energy to the utility grid with export price λ^s. Otherwise, MGO purchases energy from the utility grid with import price λ^b to meet the load demand."},{"evidence_id":"v141-b-g01-e019","location":{"location_id":"src-ed046424ff-p04-c2r2__v141-a-M01-coordination","page":4,"printed_page":null,"section":"III.C Implementation Process","anchor_text":"n- set as λs and λb, respectively. 2) Every prosumer submits ˆEgn, kn, and the role of buyer or re s","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Considering (26) and (27) belong to nonlinear programming problem, the MGO can solve (30) and obtain the internal prices p_s and p_b for the next time slot by using interior point method. The MGO broadcasts the internal prices of next time slot to all the prosumers;"},{"evidence_id":"v141-b-g02-E11","location":{"location_id":"src-ed046424ff-p06-c1r4__v141-a-M01-pricing","page":6,"printed_page":null,"section":"V.A Basic Data","anchor_text":"y g gy, g gy, ergy consumption of the microgrid in each time slot are shown in Fig. 5. Fig B. Analys","equation_id":"(30)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"example"},"source_text":"By using the basic data of the five prosumers, the SE of energy sharing game on every time slot can be achieved by solving (30). The internal prices of every time slot during the daytime are shown in Fig. 6. In time slots 7, 17-19, the internal prices are shown equally with the \\lambda^{s} and \\lambda^{b}. This is due to the fact that as the PV energy are all self-consumed by each prosumers, there is no more energy that is feasible to be traded inside the microgrid. Hence, the internal prices are constant with \\lambda^{s} and \\lambda^{b}."},{"evidence_id":"v141-b-g02-E12","location":{"location_id":"src-ed046424ff-p07-c1r3__v141-a-M01-pricing","page":7,"printed_page":null,"section":"V.B Analysis of the Internal Prices","anchor_text":"en re Fig. 9. Comparison of net energy. is D First, in time slots 10, 11, 12, and 16, as the amount ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"example"},"source_text":"First, in time slots 10, 11, 12, and 16, as the amount of selling energy is less than the buying energy, the MGO increases the selling price p_{s} and motivates the sellers to sell more energy; and second, in time slots 13 and 14, as the amount of selling energy is more than the buying energy, the MGO decreases the buying price p_{b}, and thus the buyers are encouraged to consume more extra PV energy."},{"evidence_id":"v141-b-g03-E09","location":{"location_id":"src-ed046424ff-p10-c1r2__v141-a-M01-validation","page":10,"printed_page":null,"section":"Appendix A","anchor_text":"sel s.t. λs ≤pb ≤λb, λs ≤ps ≤λb, Eb ≥Es. (27) con Therefore, from (26) and (27), considering the rel","equation_id":"(28)-(29)","figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"condition"},"source_text":"Therefore, from (26) and (27), considering the relationship between E^b and E^s, the feasible region of p_b and p_s can be divided into two parts: D_1 and D_2. If E^b \u003c E^s, then (p_b, p_s) \\in D_1. Otherwise, if E^b \\ge E^s, then (p_b, p_s) \\in D_2. Finally, we have that D_1 and D_2 meet the following conditions:\nD_1 \\cup D_2 = D, \\quad D_1 \\cap D_2 = \\phi. \\quad (28)"},{"evidence_id":"v141-b-g03-E11","location":{"location_id":"src-ed046424ff-p10-c1r3__v141-a-M01-validation","page":10,"printed_page":null,"section":"Appendix A","anchor_text":"we have the Hessian matrix H that is negative deﬁnite with [3 respect to pb and ps. Thereby, R is th","equation_id":"(30)","figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"formula"},"source_text":"The optimal internal prices of the MGO is existence and uniqueness in D_1 and D_2, which are (p_{bD_1}^*, p_{sD_1}^*) and (p_{bD_2}^*, p_{sD_2}^*), respectively. From (28), we note that the optimal internal prices in D can be represented as follows\n(p_b^*, p_s^*) = \\operatorname*{argmax}_{(p_b,p_s)}\\left(R(p_{bD_1}^*, p_{sD_1}^*), R(p_{bD_2}^*, p_{sD_2}^*)\\right). \\quad (30)\nThen we have that the optimal internal prices (p_b^*, p_s^*) is unique. Thus, there exists a unique SE and Theorem 1 is proved."},{"evidence_id":"v141-b-g02-E01","location":{"location_id":"src-ed046424ff-p06-c1r3__v141-a-M01-participation","page":6,"printed_page":null,"section":"V.A Basic Data","anchor_text":"Fig Fig. 4. Net energy of prosumers. According to the feed-in tariff of distributed PV energy in mos","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"example"},"source_text":"According to the feed-in tariff of distributed PV energy in most areas of China, \\lambda^{s} and \\lambda^{b} are set as 0.4 and 1.0 CNY/kWh, respectively, for commercial electricity price. During the daytime, the prosumers can act as buyers or sellers according to the net energy. As shown in Fig. 4, we can find that the net energy curves of Prosumer-1, Prosumer-2, and Prosumer-3 are negative for most of the time slots, so they can be treated as prosumers of seller. In contrast, the net loads of Prosumer-4 and Prosumer-5 are positive at most time, and thus they are buyers."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation","v141-a-M01-pricing","v141-a-M01-validation"],"extras":{"decision_anchor":"pricing.local","graph_fact_supports":[[{"evidence_id":"v141-b-g01-e006","quote":"Thus, we select MGO as the leader, which means that the MGO determines the buying and selling prices simultaneously."},{"evidence_id":"v141-b-g01-e019","quote":"Considering (26) and (27) belong to nonlinear programming problem, the MGO can solve (30) and obtain the internal prices p_s and p_b for the next time slot by using interior point method."}],[{"evidence_id":"v141-b-g02-E12","quote":"First, in time slots 10, 11, 12, and 16, as the amount of selling energy is less than the buying energy, the MGO increases the selling price p_{s} and motivates the sellers to sell more energy;"}],[{"evidence_id":"v141-b-g02-E12","quote":"in time slots 13 and 14, as the amount of selling energy is more than the buying energy, the MGO decreases the buying price p_{b}, and thus the buyers are encouraged to consume more extra PV energy."}],[{"evidence_id":"v141-b-g01-e007","quote":"The goal of MGO is to maximize the own profit under constraint λ^s ≤ p_s \u003c p_b ≤ λ^b."},{"evidence_id":"v141-b-g01-e014","quote":"where the internal prices p_b and p_s are decision variables."}],[{"evidence_id":"v141-b-g01-e008","quote":"For each time slot, the initial internal prices p_s and p_b can be set as λ^s and λ^b, respectively."}],[{"evidence_id":"v141-b-g03-E09","quote":"If E^b \u003c E^s, then (p_b, p_s) \\in D_1. Otherwise, if E^b \\ge E^s, then (p_b, p_s) \\in D_2."},{"evidence_id":"v141-b-g03-E11","quote":"From (28), we note that the optimal internal prices in D can be represented as follows\n(p_b^*, p_s^*) = \\operatorname*{argmax}_{(p_b,p_s)}\\left(R(p_{bD_1}^*, p_{sD_1}^*), R(p_{bD_2}^*, p_{sD_2}^*)\\right). \\quad (30)"}],[{"evidence_id":"v141-b-g02-E11","quote":"In time slots 7, 17-19, the internal prices are shown equally with the \\lambda^{s} and \\lambda^{b}. This is due to the fact that as the PV energy are all self-consumed by each prosumers, there is no more energy that is feasible to be traded inside the microgrid. Hence, the internal prices are constant with \\lambda^{s} and \\lambda^{b}."}]],"C2_formalization":{"graph_sha256":"9ba769d192b479aef47da877de11d25900f5f7e8f78a64fc754c6f6041272ffc","applicability":"formalized","reason":"The supplied B evidence contains explicit mathematical expressions for the MGO's internal buying and selling prices, the price bound, the profit objective, initialization, and the D1/D2 selection. C002 and C003 remain qualitative case observations because the source does not state an exact formula for the reported increase/decrease. B evidence remains unreviewed; this patch uses the supplied quotations without claiming independent source audit.","bindings":[{"object_id":"x_p_s","node_ids":["pricing.local"],"edge_ids":["v141-c-R008-E001"],"rationale":"p_s is the internal selling price decision at the pricing.local node. The coordination.local_operator -> pricing.local edge records that the MGO sets this internal price."},{"object_id":"x_p_b","node_ids":["pricing.local"],"edge_ids":["v141-c-R008-E001"],"rationale":"p_b is the internal buying price decision at the pricing.local node. The coordination.local_operator -> pricing.local edge records that the MGO sets this internal price."},{"object_id":"theta_lambda_s","node_ids":["pricing.local"],"edge_ids":[],"rationale":"λ^s is the utility-grid export price parameter that bounds the internal selling price and enters the profit objective at pricing.local."},{"object_id":"theta_lambda_b","node_ids":["pricing.local"],"edge_ids":[],"rationale":"λ^b is the utility-grid import price parameter that bounds the internal buying price and enters the profit objective at pricing.local."},{"object_id":"v141-c-R008-C004","node_ids":["pricing.local","coordination.local_operator"],"edge_ids":["v141-c-R008-E001"],"rationale":"C004 is the MGO's price-setting optimization with decision variables and the internal-price bound. It belongs to pricing.local, and edge E001 records the MGO's pricing role."},{"object_id":"v141-c-R008-C005","node_ids":["pricing.local"],"edge_ids":["v141-c-R008-E001"],"rationale":"C005 initializes p_s and p_b at pricing.local. Edge E001 records that the MGO performs this internal-price initialization."},{"object_id":"v141-c-R008-C006","node_ids":["pricing.local","coordination.local_operator"],"edge_ids":["v141-c-R008-E001"],"rationale":"C006 selects the optimal internal price pair across D1 and D2 at pricing.local. Edge E001 records the MGO's price-setting relation."},{"object_id":"v141-c-R008-C007","node_ids":["pricing.local"],"edge_ids":["v141-c-R008-E001"],"rationale":"C007 records the case-specific constant internal prices at pricing.local. Edge E001 records the MGO's internal-price setting relation."},{"object_id":"v141-c-R008-C008","node_ids":["pricing.local","coordination.local_operator"],"edge_ids":["v141-c-R008-E001"],"rationale":"C008 states the MGO profit function that is maximized at pricing.local. Edge E001 records the MGO's role in the pricing decision."}],"revision_requests":["B evidence v141-b-g01-e015 and v141-b-g02-E05 print the upper price bound as λ^b_n, while v141-b-g01-e007 and the appendix equations use λ^b. The formalization uses λ^b as in the primary bound; C.1 should confirm whether the import price is prosumer-indexed.","Appendix equations (26)-(27) state λ^s ≤ p_b ≤ λ^b and λ^s ≤ p_s ≤ λ^b, while the system-model constraint is λ^s ≤ p_s \u003c p_b ≤ λ^b. The formalization retains the strict p_s \u003c p_b from the system model and does not silently replace it.","Equation (30) is transcribed as printed: an argmax over a tuple of the two regional profit values. C.1 should confirm whether the intended selection is max{R(p_bD1*,p_sD1*), R(p_bD2*,p_sD2*)}; C.2 does not rewrite the source expression."]}},"quarantined_references":[]}});
